//! 🎯️ Window selection replaces only the three addressed fields of the original owned view.
use super::*;
use semio_framework_value::{RetirementDemand,retained_clone::{RetainedCloneClose,retained_clone_grant_admits}};
use semio_framework_job::OriginalSourceBinding;

pub(super) struct OriginalWindowViewBinding{binding:OriginalSourceBinding,decoder:Option<(u64,u64)>,source:Option<(usize,usize,usize,usize)>,window:usize,utility:usize,offset:usize,field:usize,phase:u8,new:ManuallyDrop<[Option<String>;3]>,old:ManuallyDrop<Option<[Option<String>;3]>>,retirement:RetainedCloneClose,pub mode_active:bool}
impl OriginalWindowViewBinding{
 pub fn admit(cx:&mut StepContext<'_>,slot:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let binding=OriginalSourceBinding::borrow(cx);let decoder=cx.native_receiving_identity();let d=Self::birth_demand();semio_framework_job::admit_original_construction(cx,slot,semio_framework_job::OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Ok((Box::new(Self{binding,decoder,source:None,window:0,utility:0,offset:0,field:0,phase:0,new:ManuallyDrop::new(Default::default()),old:ManuallyDrop::new(None),retirement:Default::default(),mode_active:false}),metadata::unit(d).progress())))}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||self.decoder.is_none()||cx.native_receiving_identity()!=self.decoder{return Err(refusal("original window projection changed its caller or decoder"))}Ok(())}
 pub fn ready(&self)->bool{self.phase==7}
 fn compare(&mut self,left:&str,right:&str,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{let n=if left.len()==right.len(){(left.len().saturating_sub(self.offset)).min(64)}else{0};if !paid(cx,2*n+3*size_of::<usize>())?{return Ok(None)}if left.len()!=right.len()||left.as_bytes()[self.offset..self.offset+n]!=right.as_bytes()[self.offset..self.offset+n]{self.offset=0;return Ok(Some(false))}self.offset+=n;if self.offset==left.len(){self.offset=0;return Ok(Some(true))}Ok(None)}
 pub fn advance(&mut self,meta:&mut ActionMeta,address:&semio_framework::manifest::ActionAddress,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let meta_id=std::ptr::from_ref(meta)as usize;let view=meta.view_state.as_mut().ok_or_else(||refusal("original action context requires its view"))?;let source=(meta_id,std::ptr::from_ref(address)as usize,view.window_instances.as_ptr()as usize,view.window_instances.len());if let Some(original)=self.source{if original!=source{return Err(refusal("original window projection changed its owned view or address"))}}else{if paid(cx,size_of::<Option<(usize,usize,usize,usize)>>())?{self.source=Some(source)}return Ok(false)}match self.phase{
  0=>{let window=view.window_instances.get(self.window).ok_or_else(||refusal("original action window is unknown"))?;if let Some(equal)=self.compare(&window.id,&address.window_instance_id,cx)?{if equal{self.phase=1}else{self.window+=1}}},
  1=>{let kind=&view.window_instances[self.window].window_kind_id;if let Some(equal)=self.compare(kind,&address.window_kind_id,cx)?{if !equal{return Err(refusal("original action window kind is foreign"))}self.phase=2}},
  2=>{if let Some((key,_))=view.active_utility_by_window_id.entry_at_rank(self.utility){if let Some(equal)=self.compare(key,&address.window_instance_id,cx)?{if equal{self.phase=3}else{self.utility+=1}}}else if paid(cx,size_of::<u8>())?{self.phase=3}},
  3=>{let text=match self.field{0=>Some(view.window_instances[self.window].id.as_str()),1=>Some(view.window_instances[self.window].window_kind_id.as_str()),2=>view.active_utility_by_window_id.entry_at_rank(self.utility).map(|(_,value)|value.as_str()),_=>return Err(refusal("original window projection field is invalid"))};if let Some(text)=text{if self.new[self.field].is_none(){let d=RetirementDemand{copy_bytes:size_of::<Option<String>>(),capacity_bytes:text.len(),depth:1,release_bytes:0};metadata::receive(cx,d,|control,_|{control.charge(d.capacity_bytes)?;self.new[self.field]=Some(String::with_capacity(text.len()));Ok(metadata::unit(d))})?;}else{let mut end=(self.offset+64).min(text.len());while !text.is_char_boundary(end){end-=1}if paid(cx,end-self.offset+2*size_of::<usize>())?{self.new[self.field].as_mut().unwrap().push_str(&text[self.offset..end]);self.offset=end;if end==text.len(){self.offset=0;self.field+=1}}}}else if paid(cx,size_of::<usize>())?{self.field+=1}if self.field==3{self.phase=4}},
  4=>{if paid(cx,6*size_of::<Option<String>>())?{*self.old=Some([view.window_id.take(),view.active_window_kind_id.take(),view.active_utility_id.take()]);view.window_id=self.new[0].take();view.active_window_kind_id=self.new[1].take();view.active_utility_id=self.new[2].take();self.phase=5}},
  5=>{if self.close_old(cx)?{self.phase=6}},
  6=>{if let Some(mode)=view.active_mode_id.as_deref(){if let Some(equal)=self.compare(mode,&address.mode_id,cx)?{self.mode_active=equal;self.phase=7}}else if paid(cx,size_of::<bool>())?{self.mode_active=false;self.phase=7}},
  7=>{},_=>return Err(refusal("original window projection phase is invalid"))}Ok(self.ready())}
 fn close_old(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let body=cx.retained_grant().maximum_copy_bytes;if !self.retirement.is_empty(){let mut selected=self.retirement.select(body)?;let d=selected.demands();semio_framework_job::close_original_retained_step(cx,d,|g|selected.step(g))?;return Ok(false)}if self.old.is_some(){let d=self.retirement.next_owner_demands::<[Option<String>;3]>(true,&None,body)?;semio_framework_job::close_original_retained_step(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.old,g)?.unwrap_or(semio_framework_value::RetainedCloneStep::Complete(Default::default()))))?;return Ok(false)}Ok(true)}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.close_old(cx)?{return Ok(false)}if self.new.iter().any(Option::is_some){let d=RetirementDemand{copy_bytes:2*size_of::<[Option<String>;3]>(),depth:1,..Default::default()};if !cx.retirement_should_yield()&&retained_clone_grant_admits(cx.retained_grant(),d){*self.old=Some(std::mem::take(&mut*self.new));cx.consume_retained(metadata::unit(d).progress())?;cx.consume_fuel(1)}return Ok(false)}Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.new.iter().all(Option::is_none)&&self.old.is_none()&&self.retirement.is_empty()}
 pub fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Self>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalWindowViewBinding{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original window projection requires funded closure")}}
